$q=new WP_REST_Request('GET','/hpads/v1/devices/'.$device['id'].'/playlist');$q->set_param('_hpads_authenticated_device',$device['id']);$api=HPADS_API::playlist($q)->get_data();mix_ok(!empty($api['playback_mix']['enabled']) && array_key_exists('primary',$api) && array_key_exists('house',$api),'device API adds mix while preserving legacy payload slots');
$q=new WP_REST_Request('POST','/hpads/v1/devices/'.$device['id'].'/heartbeat');$q->set_header('Content-Type','application/json');$q->set_body(wp_json_encode(['active_version'=>$playlists[1]['data']['published_version'],'state'=>'playing']));$q->set_param('_hpads_authenticated_device',$device['id']);mix_ok(!is_wp_error(HPADS_API::heartbeat($q)),'heartbeat accepts active mixed playlist outside legacy slots');
$device=mix_native($device,['hwads_mix_settings'=>1,'playback_mix_mode'=>'legacy']);mix_ok(!HPADS_Playback_Mix::payload($device,$location)['enabled'],'device-specific legacy override disables inherited mix');$device=mix_native($device,['hwads_mix_settings'=>1,'playback_mix_mode'=>'inherit']);mix_ok(HPADS_Playback_Mix::payload($device,$location)['enabled'],'native device source selector restores location inheritance');
$old=['primary_playlist'=>$p1['id']];mix_ok(HPADS_Playback_Mix::mode($old)==='legacy' && HPADS_Playback_Mix::mode([])==='inherit','existing explicit device assignments are preserved, unassigned devices inherit');
