$unpublished=mix_record('playlist','Unpublished mix draft',$location['id'],['purpose'=>'primary']);mix_ok(!isset(HPADS_Playback_Mix::choices($location['id'])[$unpublished['id']]),'unpublished playlists excluded from picker');
